// Not a -data.js file on purpose: the What's New generator must ignore it.
// ============================================

// ---------- CPT surgical package / CMS global surgery ----------
window.SURG_PKG_QUESTIONS = [
    { q: 'Per CPT, which E/M service is included in the surgical package?', opts: ['The E/M visit at which the decision for surgery was made, whenever it occurred', 'E/M service(s) subsequent to the decision for surgery on the day before and/or day of surgery, including the history and physical', 'All E/M visits in the 30 days before surgery', 'No E/M service is ever included'], a: 1, why: 'CPT defines the package to include E/M services after the decision for surgery on the day before and/or the day of surgery (including H&P). The visit where surgery was decided is separately reportable (modifier 57 for a major procedure).', cite: 'CPT Surgery Guidelines — CPT Surgical Package Definition' },
    { q: 'Which type of anesthesia is included in the CPT surgical package?', opts: ['General anesthesia', 'Monitored anesthesia care', 'Local infiltration, metacarpal/metatarsal/digital block, or topical anesthesia', 'Spinal anesthesia'], a: 2, why: 'Only local infiltration, digital/metacarpal/metatarsal blocks and topical anesthesia are part of the package. General, regional and MAC are reported by the anesthesia provider.', cite: 'CPT Surgery Guidelines — CPT Surgical Package Definition' },
    { q: 'Which of these is NOT listed by CPT as part of the surgical package?', opts: ['Dictating operative notes', 'Talking with the family and other physicians', 'Evaluating the patient in the postanesthesia recovery area', 'Treatment of a postoperative complication'], a: 3, why: 'CPT includes immediate postoperative care (op notes, family discussion, orders, PACU evaluation) and typical follow-up. CPT states that complications, exacerbations, recurrence or other diseases requiring additional services are NOT included — note that Medicare treats complications differently.', cite: 'CPT Surgery Guidelines — Follow-Up Care for Therapeutic Surgical Procedures' },
    { q: 'How many days does a Medicare MAJOR surgery global period cover after the day of surgery?', opts: ['10', '30', '90', '120'], a: 2, why: 'Major procedures carry a 90-day postoperative period, plus the day of surgery and one preoperative day — 92 days in all.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'A Medicare 90-day global period includes how many PREoperative days?', opts: ['0', '1', '3', '7'], a: 1, why: 'Major (090) procedures include the day before surgery. Minor (010 and 000) procedures include no preoperative day.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'What is the total span of a Medicare 10-day global period?', opts: ['10 days', '11 days — the day of surgery plus 10 days after', '12 days — one day before, the day of, and 10 days after', '14 days'], a: 1, why: 'Minor procedures with a 10-day global include the day of surgery and the 10 days following it; there is no preoperative day.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'An endoscopy carries a 0-day global period. What does that cover?', opts: ['Nothing — every service is separately payable', 'The day of the procedure only', 'The day of and the day after', 'The day before and the day of'], a: 1, why: '000 = the global period is the day of the procedure only. Visits on later days are payable, but an E/M on the same day still needs modifier 25 and must be significant and separately identifiable.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'Under Medicare rules, treatment of a postoperative complication that does NOT require a return to the operating room is…', opts: ['Separately payable with modifier 78', 'Separately payable with modifier 24', 'Included in the global surgery payment', 'Separately payable with modifier 79'], a: 2, why: 'Medicare includes all additional medical or surgical services required because of complications that do not require additional trips to the OR. CPT guidance differs — know which rules your payer follows.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'A patient returns to the OR during the global period for bleeding related to the original surgery. Which modifier?', opts: ['58', '78', '79', '59'], a: 1, why: '78 = unplanned return to the operating/procedure room by the same physician for a related procedure during the postoperative period. Medicare pays only the intraoperative portion and no new global period starts.', cite: 'CMS MLN907166 Global Surgery; CPT Appendix A' },
    { q: 'Which modifier does NOT start a new global period?', opts: ['58', '78', '79', 'All three start a new global period'], a: 1, why: '78 pays the intraoperative portion only and the original global continues. 58 (staged/related) and 79 (unrelated) each begin a new global period.', cite: 'CMS Claims Processing Manual ch. 12 §40.2' },
    { q: 'A staged procedure planned at the time of the original surgery is performed during the global period. Which modifier?', opts: ['58', '78', '79', '22'], a: 0, why: '58 = staged or related procedure by the same physician during the postoperative period: planned prospectively, more extensive than the original, or therapy following a diagnostic procedure. A new global period begins.', cite: 'CPT Appendix A; CMS MLN907166' },
    { q: 'During the 90-day global for a hip replacement, the surgeon treats the same patient for a new, unrelated wrist fracture in the OR. Which modifier on the wrist procedure?', opts: ['58', '78', '79', '24'], a: 2, why: '79 = unrelated procedure by the same physician during the postoperative period. A new global period begins for the wrist procedure.', cite: 'CPT Appendix A; CMS MLN907166' },
    { q: 'An E/M visit for a problem unrelated to the surgery, during the global period, is reported with…', opts: ['Modifier 24', 'Modifier 25', 'Modifier 57', 'No modifier — it is included'], a: 0, why: '24 = unrelated E/M service by the same physician during a postoperative period. Documentation must show the visit was unrelated to the surgery.', cite: 'CPT Appendix A; CMS MLN907166' },
    { q: 'The surgeon sees a new patient, decides a MAJOR (90-day) surgery is needed, and operates the next day. The decision visit is reported with…', opts: ['Modifier 25', 'Modifier 57', 'Modifier 24', 'It is included in the package'], a: 1, why: '57 = decision for surgery. Medicare: use it on the E/M the day before or the day of a major procedure. Without it the visit is bundled into the global.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'A significant, separately identifiable E/M on the same day as a MINOR (0- or 10-day) procedure is reported with…', opts: ['Modifier 57', 'Modifier 25', 'Modifier 24', 'Modifier 59'], a: 1, why: '25 is for minor procedures; 57 is for major procedures. The work of deciding to perform a minor procedure is included in the procedure itself.', cite: 'CMS MLN907166 Global Surgery; CPT Appendix A' },
    { q: 'Which split-care modifier means "postoperative management only"?', opts: ['54', '55', '56', '62'], a: 1, why: '54 = surgical care only · 55 = postoperative management only · 56 = preoperative management only. Used when care is formally transferred between physicians.', cite: 'CPT Appendix A; CMS MLN907166' },
    { q: 'Which split-care modifier does the operating surgeon use when another physician provides the postoperative care?', opts: ['54', '55', '56', '80'], a: 0, why: '54 = surgical care only. The physician taking over follow-up reports the same surgical code with 55.', cite: 'CPT Appendix A; CMS MLN907166' },
    { q: 'Which of these is separately payable during a Medicare global period?', opts: ['Dressing changes and local incision care', 'Removal of sutures or staples by the surgeon', 'Diagnostic tests and procedures, including diagnostic radiology', 'Routine postoperative pain management by the surgeon'], a: 2, why: 'Diagnostic tests and procedures are not part of the global package. Dressing changes, suture removal, routine pain management and postoperative visits related to recovery are included.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'Which of these is included in the Medicare global package?', opts: ['Critical care for a seriously burned or injured patient unrelated to the surgery', 'Immunosuppressive therapy after a transplant', 'Treatment of the underlying condition or an added course of treatment that is not part of normal recovery', 'Insertion, irrigation and removal of urinary catheters, routine peripheral IV lines and nasogastric tubes'], a: 3, why: 'Miscellaneous services — catheters, routine IV lines, NG and rectal tubes, tracheostomy tube changes — are included. The other three are listed by CMS as NOT included.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'If a less extensive procedure fails and a more extensive procedure is required during the global period, the second procedure is…', opts: ['Bundled into the first', 'Payable separately', 'Reported with modifier 52', 'Reported instead of the first; the first is voided'], a: 1, why: 'CMS lists this case explicitly as not included in the global package: the more extensive procedure is payable separately (typically with modifier 58).', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'A physician who did NOT perform the surgery sees the patient during the global period (no formal transfer of care). Those services are…', opts: ['Included in the surgeon’s global payment', 'Payable separately to that physician', 'Payable only with modifier 55', 'Payable only with modifier 24'], a: 1, why: 'The global package applies to the surgeon (and same-group, same-specialty physicians). Services of other physicians are not included unless care was formally transferred.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'On the Medicare Physician Fee Schedule, a global indicator of XXX means…', opts: ['90-day global', 'The global concept does not apply to the code', 'Add-on code included in the primary procedure’s global', 'Maternity code with a special global'], a: 1, why: 'XXX = global concept does not apply (E/M, most radiology and lab). 000/010/090 = days. ZZZ = add-on code, part of another service’s global. MMM = maternity. YYY = contractor-determined.', cite: 'CMS MPFS Relative Value File — Global Days indicator' },
    { q: 'What does global indicator ZZZ mean?', opts: ['Zero-day global', 'The code is an add-on, always included in the global period of the primary procedure', 'Carrier-priced', 'Maternity'], a: 1, why: 'ZZZ codes are add-on codes; they follow the global period of the primary procedure they are reported with.', cite: 'CMS MPFS Relative Value File — Global Days indicator' },
    { q: 'Under Medicare’s multiple procedure payment reduction, the second through fifth procedures by the same physician on the same day are typically paid at…', opts: ['100%', '75%', '50%', '25%'], a: 2, why: 'The highest-valued procedure is paid at 100% and the next four at 50% of the fee schedule amount (modifier 51 concept; many payers append 51 automatically).', cite: 'CMS Claims Processing Manual ch. 12 §40.6' },
    { q: 'Modifier 22 (increased procedural services) requires…', opts: ['Nothing beyond the modifier', 'Documentation of why the work was substantially greater than typically required', 'A second surgeon', 'A 0-day global code'], a: 1, why: '22 is used when the work is substantially greater than usual; documentation must support the increased intensity, time, technical difficulty or severity, and payment is typically reviewed manually.', cite: 'CPT Appendix A' },
    { q: 'Which modifier indicates two surgeons each performing a distinct part of a single procedure?', opts: ['62', '66', '80', '81'], a: 0, why: '62 = two surgeons (co-surgeons), each reporting the same code with 62. 66 = surgical team. 80/81/82 = assistant surgeons; AS = non-physician assistant.', cite: 'CPT Appendix A' },
    { q: 'A procedure is discontinued after anesthesia is started because the patient becomes unstable. The physician reports the code with…', opts: ['Modifier 52', 'Modifier 53', 'Modifier 73', 'Modifier 74'], a: 1, why: '53 = discontinued procedure (physician reporting). 73 and 74 are for the facility (ASC/hospital outpatient) before and after anesthesia respectively. 52 = reduced services where the procedure was partially reduced, not stopped for patient risk.', cite: 'CPT Appendix A' },
    { q: 'A bilateral procedure performed at the same session on a code that is not inherently bilateral is reported with…', opts: ['Modifier 50', 'Modifier 51', 'Modifier 59', 'Two lines with RT and LT and no bilateral adjustment'], a: 0, why: '50 = bilateral procedure. Medicare pays 150% of the fee schedule amount when the code’s bilateral indicator is 1.', cite: 'CPT Appendix A; CMS Claims Processing Manual ch. 12 §40.7' },
    { q: 'Postoperative visits related to recovery from the surgery, during the global period, are…', opts: ['Reported with 99024 and included in the global payment', 'Reported with 99213 and paid separately', 'Reported with 99024 and paid separately', 'Not reported at all'], a: 0, why: '99024 = postoperative follow-up visit included in the surgical package. It carries no separate payment but is reported (CMS has required it in some states for data collection).', cite: 'CPT 99024; CMS MLN907166' },
    { q: 'Which statement about CPT versus Medicare on complications is TRUE?', opts: ['Both include all complications in the package', 'CPT excludes complications from the package; Medicare includes complications that do not require a return to the OR', 'CPT includes complications; Medicare excludes them', 'Neither addresses complications'], a: 1, why: 'CPT: complications, exacerbations and recurrence requiring additional services are not included. Medicare: included unless they require a return to the operating room (then modifier 78).', cite: 'CPT Surgery Guidelines; CMS MLN907166' },
    { q: 'Supplies during a Medicare global period are…', opts: ['Always paid separately', 'Included, except those CMS identifies as exclusions', 'Paid separately only with modifier 59', 'Billed by the facility only'], a: 1, why: 'CMS includes supplies in the global package except for those identified as exclusions.', cite: 'CMS MLN907166 Global Surgery' },
    { q: 'The surgeon performs a 0-day global procedure and, on the same day, a significant separately identifiable E/M for a different problem. What is reported?', opts: ['The procedure only', 'The procedure and the E/M with modifier 25', 'The procedure and the E/M with modifier 57', 'The E/M only'], a: 1, why: 'Same-day E/M with a minor procedure needs modifier 25 and must be significant and separately identifiable from the usual pre- and post-work of the procedure.', cite: 'CMS MLN907166 Global Surgery' }
];

// In or out of the package? [scenario, 'in' | 'mod' | 'out', explanation]
//   in  = included in the global package, not separately billable
//   mod = separately reportable, but only with the right modifier
//   out = separately reportable, no global-surgery modifier needed
