window.DRG_QUESTIONS = [
    { q: 'What is the first step the MS-DRG grouper takes with a discharge (after the Pre-MDC check)?', opts: ['Assigns a severity tier', 'Assigns the Major Diagnostic Category from the principal diagnosis', 'Looks for an O.R. procedure', 'Calculates the relative weight'], a: 1, why: 'The principal diagnosis places the case in one of 25 MDCs (organ system or etiology). Then the grouper checks for an O.R. procedure (surgical vs medical partition), then CC/MCC severity.', cite: 'CMS MS-DRG Definitions Manual — Design and development' },
    { q: 'What determines whether a case goes to the SURGICAL partition of an MDC?', opts: ['Any procedure code', 'The presence of a procedure the grouper classifies as an O.R. procedure', 'A CPT surgery code', 'Length of stay over 3 days'], a: 1, why: 'Only ICD-10-PCS procedures designated as O.R. procedures move the case to the surgical partition. Non-O.R. procedures (e.g., most endoscopies) leave it medical.', cite: 'CMS MS-DRG Definitions Manual — Surgical hierarchy' },
    { q: 'A patient has two O.R. procedures during the stay. Which one drives the DRG?', opts: ['The first one performed', 'The one with the higher CPT value', 'The one in the highest-ranked surgical class in the MDC’s surgical hierarchy', 'The one coded first on the claim'], a: 2, why: 'Each MDC has a surgical hierarchy; the case is assigned to the surgical class that is highest in the hierarchy, regardless of sequence.', cite: 'CMS MS-DRG Definitions Manual — Surgical hierarchy' },
    { q: 'What are the three severity levels used by MS-DRGs?', opts: ['Minor, moderate, major', 'With MCC, with CC, without CC/MCC', 'Level 1, 2, 3', 'Low, medium, high risk of mortality'], a: 1, why: 'MS-DRGs split many base DRGs by secondary diagnoses: major complication/comorbidity (MCC), complication/comorbidity (CC), or neither. Not every base DRG has all three splits.', cite: 'CMS MS-DRG Definitions Manual — CC/MCC' },
    { q: 'A secondary diagnosis is on the CC list, but it is closely related to the principal diagnosis. What happens?', opts: ['It still counts as a CC', 'It is excluded — it does not count as a CC for this principal diagnosis', 'It counts as an MCC instead', 'The case is rejected'], a: 1, why: 'The CC Exclusion List removes a CC/MCC when it is closely related to (or inherent in) the principal diagnosis, e.g., chronic systolic heart failure with a principal of acute on chronic systolic heart failure.', cite: 'CMS MS-DRG Definitions Manual — CC Exclusion List' },
    { q: 'Which secondary diagnosis affects MS-DRG assignment?', opts: ['Only the first-listed secondary diagnosis', 'Any secondary diagnosis on the CC or MCC list that is not excluded for that principal diagnosis', 'Only chronic conditions', 'Only conditions present on admission'], a: 1, why: 'One qualifying MCC puts the case in the "with MCC" tier; one qualifying CC (and no MCC) puts it in "with CC". The number of CCs beyond that does not change the MS-DRG.', cite: 'CMS MS-DRG Definitions Manual — CC/MCC' },
    { q: 'Hospital payment under IPPS is basically…', opts: ['Charges × cost-to-charge ratio', 'The hospital’s standardized base rate × the MS-DRG relative weight (plus adjustments)', 'Per diem × length of stay', 'The DRG relative weight × 1,000'], a: 1, why: 'Payment = base payment rate (operating + capital, wage-index adjusted) × relative weight, then add-ons such as IME, DSH, new technology and outliers.', cite: 'CMS Acute Inpatient PPS' },
    { q: 'A relative weight of 2.0 means the DRG…', opts: ['Pays twice the hospital’s charges', 'Uses about twice the resources of the average Medicare case (weight 1.0)', 'Has a 2-day expected stay', 'Needs two CCs'], a: 1, why: 'Weights are relative to the national average case, which is normalized to 1.0.', cite: 'CMS Acute Inpatient PPS' },
    { q: 'Case Mix Index (CMI) is…', opts: ['The number of DRGs a hospital uses', 'The average MS-DRG relative weight of a hospital’s discharges', 'Total charges divided by discharges', 'The percentage of surgical cases'], a: 1, why: 'CMI = sum of relative weights ÷ number of discharges. A higher CMI reflects a more resource-intensive (or more completely documented and coded) case mix.', cite: 'CMS Acute Inpatient PPS' },
    { q: 'The UHDDS defines the principal diagnosis as…', opts: ['The most severe condition', 'The condition established after study to be chiefly responsible for occasioning the admission', 'The first condition listed by the physician', 'The reason for the longest part of the stay'], a: 1, why: 'The UHDDS definition applies to inpatient reporting and drives MDC assignment.', cite: 'UHDDS; ICD-10-CM Official Guidelines Section II' },
    { q: 'What does Present On Admission (POA) indicator "N" trigger for a hospital-acquired condition (HAC) on the CMS list?', opts: ['Nothing', 'The condition is not counted as a CC/MCC when it would be the only reason for a higher-paying DRG', 'The claim is denied', 'An outlier payment'], a: 1, why: 'Under the HAC payment provision, a selected condition that was not present on admission does not move the case to a higher-severity MS-DRG.', cite: 'CMS Hospital-Acquired Conditions (Present on Admission Indicator)' },
    { q: 'POA indicator "Y" means…', opts: ['Yes, present at the time of inpatient admission', 'Unknown', 'Clinically undetermined', 'Exempt from reporting'], a: 0, why: 'Y = present on admission · N = not present · U = documentation insufficient · W = clinically undetermined · 1 (or blank) = exempt.', cite: 'ICD-10-CM Official Guidelines Appendix I' },
    { q: 'When is a cost outlier payment made?', opts: ['Whenever LOS exceeds the geometric mean', 'When the hospital’s costs for the case exceed the DRG payment plus a fixed-loss threshold', 'For every surgical DRG', 'When the patient is transferred'], a: 1, why: 'Outlier payments cover a portion of costs above the DRG payment plus the annually set fixed-loss amount.', cite: 'CMS Acute Inpatient PPS — Outlier payments' },
    { q: 'A patient is transferred to another acute care hospital after a 1-day stay in a DRG with a geometric mean LOS of 5. The transferring hospital is paid…', opts: ['The full DRG payment', 'A per-diem amount based on the DRG payment, up to the full amount', 'Nothing', 'Half the DRG payment'], a: 1, why: 'Transfers to another IPPS hospital (and to post-acute settings for designated DRGs) are paid per diem when LOS is short relative to the GMLOS.', cite: 'CMS Acute Inpatient PPS — Transfer policy' },
    { q: 'What is the "3-day payment window"?', opts: ['Admissions must last 3 days', 'Outpatient diagnostic services and related non-diagnostic services within 3 days before an inpatient admission are bundled into the inpatient claim', 'Claims must be filed within 3 days', 'A 3-day readmission penalty'], a: 1, why: 'Services furnished by the admitting hospital (or wholly owned entities) in the 3 days before admission are included in the IPPS payment.', cite: 'CMS Claims Processing Manual ch. 3 §40.3' },
    { q: 'Where do heart transplant, ECMO and tracheostomy with ventilation over 96 hours group?', opts: ['MDC 5', 'MDC 4', 'Pre-MDC — assigned before the MDC step', 'MDC 24'], a: 2, why: 'Pre-MDC DRGs capture extremely resource-intensive procedures (transplants, ECMO, tracheostomy with prolonged ventilation) regardless of the principal diagnosis.', cite: 'CMS MS-DRG Definitions Manual — Pre-MDC' },
    { q: 'An O.R. procedure unrelated to the principal diagnosis is performed. The case groups to…', opts: ['The medical DRG for the principal diagnosis', 'MS-DRGs 981–989: O.R. procedure unrelated to the principal diagnosis', 'Pre-MDC', 'The surgical DRG for the procedure’s own MDC'], a: 1, why: '981–983 (extensive) and 987–989 (non-extensive) capture O.R. procedures that do not belong to the principal diagnosis’s MDC — a red flag worth double-checking the coding.', cite: 'CMS MS-DRG Definitions Manual — Unrelated O.R. procedures' },
    { q: 'MS-DRG definitions and relative weights are updated…', opts: ['Monthly', 'Every October 1 with the federal fiscal year', 'Every January 1', 'Every 5 years'], a: 1, why: 'The IPPS final rule takes effect October 1; ICD-10-CM/PCS codes update at the same time (with an April update for some codes).', cite: 'CMS Acute Inpatient PPS' },
    { q: 'Which hospitals are NOT paid under IPPS?', opts: ['Teaching hospitals', 'Critical Access Hospitals, which are paid on reasonable cost', 'Urban hospitals', 'Hospitals with over 500 beds'], a: 1, why: 'CAHs (25 beds or fewer, rural) are paid 101% of reasonable cost, not by DRG. Psychiatric, rehab and LTC hospitals have their own PPS.', cite: 'CMS Critical Access Hospitals' },
    { q: 'What is GMLOS?', opts: ['Gross Medicare length of stay', 'The geometric mean length of stay for the DRG, used in the transfer policy', 'The maximum allowed stay', 'A readmission measure'], a: 1, why: 'GMLOS (geometric mean) dampens the effect of extreme stays; AMLOS is the arithmetic mean.', cite: 'CMS MS-DRG Table 5' },
    { q: 'APR-DRGs differ from MS-DRGs mainly in that they…', opts: ['Are used only for outpatients', 'Add four severity-of-illness and four risk-of-mortality subclasses to each base DRG', 'Have no severity adjustment', 'Are maintained by CMS'], a: 1, why: '3M APR-DRGs (used by many Medicaid programs, including Medi-Cal, and commercial payers) assign SOI 1–4 and ROM 1–4 rather than the MCC/CC/none tiers.', cite: '3M APR-DRG methodology; DHCS Medi-Cal APR-DRG' },
    { q: 'Which action most directly raises a hospital’s CMI legitimately?', opts: ['Admitting more patients', 'Complete physician documentation and coding of all reportable secondary diagnoses (query when unclear)', 'Using more Z codes', 'Shorter stays'], a: 1, why: 'Captured, documented MCCs and CCs move cases to accurate higher-weight tiers. Coding a condition that is not documented is upcoding.', cite: 'CMS MS-DRG Definitions Manual — CC/MCC; AHIMA Query guidance' },
    { q: 'Which of these is an MCC?', opts: ['Essential hypertension (I10)', 'Acute respiratory failure with hypoxia (J96.01)', 'Type 2 diabetes without complications (E11.9)', 'Unspecified atrial fibrillation (I48.91)'], a: 1, why: 'Acute respiratory failure is a major complication/comorbidity; the other three are non-CCs.', cite: 'CMS MS-DRG Definitions Manual Appendix C' },
    { q: 'Which of these is a CC (not an MCC)?', opts: ['Septic shock (R65.21)', 'Acute kidney failure, unspecified (N17.9)', 'Severe protein-calorie malnutrition (E43)', 'Hypertension (I10)'], a: 1, why: 'N17.9 is a CC. Septic shock and severe malnutrition are MCCs; hypertension is a non-CC.', cite: 'CMS MS-DRG Definitions Manual Appendix C' },
    { q: 'A base DRG splits only into "with MCC" and "without MCC". A case has one CC and no MCC. Which tier?', opts: ['With MCC', 'Without MCC', 'With CC', 'It cannot be grouped'], a: 1, why: 'In a two-way split, a CC alone does not move the case up — only an MCC does.', cite: 'CMS MS-DRG Definitions Manual — CC/MCC' },
    { q: 'The discharge disposition code matters to MS-DRG payment because…', opts: ['It changes the MDC', 'It triggers the post-acute care transfer policy for designated DRGs when the patient goes to SNF, home health, IRF, etc.', 'It sets the relative weight', 'It does not matter'], a: 1, why: 'For post-acute transfer DRGs, a short stay followed by transfer to a post-acute setting is paid per diem.', cite: 'CMS Acute Inpatient PPS — Post-acute care transfer policy' }
];

